def calculate_a(n):
    if n == 1:
        return 0

    # Memoization dictionary to store calculated values
    memo = {1: 0}

    def get_a(k):
        if k in memo:
            return memo[k]

        if k % 2 == 0:
            # n = 2k, so k_prime = k/2
            k_prime = k // 2
            result = 2 * get_a(k_prime) + k_prime
        else:
            # n = 2k + 1, so k_prime = (k-1)/2
            k_prime = (k - 1) // 2
            # a_{2k+1} = a_k + a_{k+1} + k
            # Here k_prime = (k-1)/2, so k = 2*k_prime + 1
            # We need a_{2k'+1} = a_{k'} + a_{k'+1} + k'
            result = get_a(k_prime) + get_a(k_prime + 1) + k_prime

        memo[k] = result
        return result

    return get_a(n)

# Calculate a_2025
a_2025 = calculate_a(2025)
print(f"a_2025 = {a_2025}")
